contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters for deposit and cashout amounts
    function run(uint depositAmount, uint cashOutAmount) public payable {
        require(address(this).balance >= depositAmount, "not enough test balance for deposit");
        // record before-values
        uint beforeMapping = c.balances(address(this));
        uint beforeContractBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        // perform Deposit: call with value depositAmount
        bool depositReverted = false;
        // Deposit is payable; call and catch revert
        try c.Deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // perform CashOut of cashOutAmount
        bool cashoutReverted = false;
        try c.CashOut(cashOutAmount) {
            cashoutReverted = false;
        } catch {
            cashoutReverted = true;
        }

        // read after-values
        uint afterMapping = c.balances(address(this));
        uint afterContractBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;

        // The invariant to assert (general rule):
        // 1) The recorded balances mapping for this address never decreases except when a CashOut succeeded.
        //    That is, if CashOut did not succeed then afterMapping >= beforeMapping (modulo successful deposit).
        // 2) If Deposit succeeded, mapping increases by depositAmount. If Deposit reverted, mapping did not increase because of deposit.
        // 3) If CashOut succeeded, mapping decreases by cashOutAmount and c's balance decreases by cashOutAmount and this contract's balance increases by cashOutAmount.
        // Combine into one general assert covering relations between before/after and the revert flags.

        assert(
            // deposit effects
            (
                depositReverted ? (afterMapping == beforeMapping) : (afterMapping == beforeMapping + depositAmount)
            )
            // cashout effects must also hold simultaneously
            && (
                cashoutReverted ? (
                    // if cashout reverted then mapping must not have decreased and balances must reflect only deposit effect
                    afterMapping >= (beforeMapping) && afterContractBalance == beforeContractBalance + (depositReverted ? 0 : depositAmount)
                ) : (
                    // if cashout succeeded mapping decreased by cashOutAmount and contract balance decreased accordingly and this contract received the ether
                    afterMapping + cashOutAmount == (depositReverted ? beforeMapping : beforeMapping + depositAmount)
                    && beforeContractBalance + (depositReverted ? 0 : depositAmount) == afterContractBalance + cashOutAmount
                    && afterThisBalance == beforeThisBalance - (depositReverted ? 0 : depositAmount) + cashOutAmount
                )
            )
        );
    }

    // allow receiving ether when cashing out
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try a CashOut of amount am (no deposits here)
    function run(uint am) public payable {
        // ensure this test contract has enough external balance to cover any future calls that might send Ether from it
        require(address(this).balance >= 0);

        // record before values
        uint beforeMap = c.balances(address(this));
        uint beforeCbal = address(c).balance;
        uint beforeThis = address(this).balance;

        // try CashOut; catch revert
        bool cashoutReverted;
        try c.CashOut(am) {
            cashoutReverted = false;
        } catch {
            cashoutReverted = true;
        }

        uint afterMap = c.balances(address(this));
        uint afterCbal = address(c).balance;
        uint afterThis = address(this).balance;

        // General property:
        // - If CashOut succeeded then mapping decreased by exactly am and contract lost am and this received am.
        // - If CashOut reverted then mapping and ether balances are unchanged.
        assert(
            cashoutReverted
            ? (afterMap == beforeMap && afterCbal == beforeCbal && afterThis == beforeThis)
            : (beforeMap >= am && afterMap + am == beforeMap && beforeCbal == afterCbal + am && afterThis == beforeThis + am)
        );
    }

    // allow receiving ether when cashing out
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: attempt a Deposit of amount 'amount'
    function run(uint amount) public payable {
        // ensure this contract can send the amount when calling Deposit (call uses this contract's balance)
        require(address(this).balance >= amount);

        // read before-values
        uint beforeMap = c.balances(address(this));
        uint beforeCbal = address(c).balance;

        // perform Deposit sending 'amount' wei
        bool didRevert;
        try c.Deposit{value: amount}() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // read after-values
        uint afterMap = c.balances(address(this));
        uint afterCbal = address(c).balance;

        // General property:
        // - If amount >= MinDeposit then Deposit should not revert, and both the mapping entry
        //   for this address and the contract's Ether balance increase exactly by amount.
        // - If amount < MinDeposit then Deposit is a no-op (it does not revert) and neither the mapping
        //   nor the contract balance change.
        // Note: According to C, Deposit uses an if(msg.value >= MinDeposit) { ... } without revert, so
        // both branches should not revert. We therefore assert didRevert == false and state changes
        // match the two cases.
        uint minDep = c.MinDeposit();

        assert(
            // Deposit should never revert
            didRevert == false
            && (
                // case: qualifies as deposit
                (amount >= minDep
                    ? (afterMap == beforeMap + amount && afterCbal == beforeCbal + amount)
                    // case: below minimum deposit -> no state change
                    : (afterMap == beforeMap && afterCbal == beforeCbal))
            )
        );
    }

    // allow receiving ether when testing
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test driving CashOut with amount 'amt'
    function run(uint amt) public payable {
        // Ensure this test contract can receive refunds and can send deposits if needed.
        // We'll first ensure there is enough recorded balance in c for this contract by performing
        // a Deposit of >= MinDeposit if necessary. To send Ether we must have it in this contract.
        // Require that the tester has enough Ether to perform an optional deposit.
        require(address(this).balance >= amt);

        // Read before-values
        uint beforeMap = c.balances(address(this));
        uint beforeCTestBal = address(c).balance;
        uint beforeThisBal = address(this).balance;

        // If the mapping does not have at least amt, try to top it up by depositing exactly (needed)
        // but only if amt >= MinDeposit; otherwise depositing won't change mapping so skip.
        uint minDep = c.MinDeposit();
        if (amt > beforeMap && minDep <= address(this).balance) {
            uint need = amt - beforeMap;
            // If need < minDep, we still must deposit at least minDep to increase mapping; so deposit max(need,minDep)
            uint toSend = need >= minDep ? need : minDep;
            // ensure we have funds to send
            if (address(this).balance >= toSend) {
                // perform Deposit; it may or may not revert (it shouldn't in C), but we don't catch here
                // The call is top-level and changes c's state if it qualifies.
                c.Deposit{value: toSend}();
            }
        }

        // Re-read before-values after possible deposit
        uint midMap = c.balances(address(this));
        uint midCbal = address(c).balance;
        uint midThisBal = address(this).balance;

        // Now attempt CashOut of amt and catch whether it reverted
        bool reverted;
        try c.CashOut(amt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterMap = c.balances(address(this));
        uint afterCbal = address(c).balance;
        uint afterThisBal = address(this).balance;

        // Assert the general invariant:
        // - If CashOut did not revert then the mapping decreased by exactly amt and the tester got exactly amt more Wei,
        //   and the contract's balance decreased by exactly amt.
        // - If CashOut reverted then none of those three observable values changed.
        assert(
            reverted
            ? (afterMap == midMap && afterCbal == midCbal && afterThisBal == midThisBal)
            : (midMap >= amt && afterMap == midMap - amt && afterCbal + amt == midCbal && afterThisBal == midThisBal + amt)
        );
    }

    // allow receiving ether when testing
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test driving Deposit (optional) and CashOut with amount 'amt' and optional top-up 'topup'
    function run(uint amt, uint topup) public payable {
        // ensure this test contract has enough Ether to send any topup or to receive cashouts
        require(address(this).balance >= topup);

        // Read initial observable state
        uint beforeMap = c.balances(address(this));
        uint beforeCbal = address(c).balance;
        uint beforeThisBal = address(this).balance;

        // If caller supplied a topup > 0, perform a Deposit of that exact amount as a top-level state-changing call.
        // The Deposit will only affect c if topup >= MinDeposit; we don't wrap in try/catch so revert would revert this test.
        if (topup > 0) {
            c.Deposit{value: topup}();
        }

        // Read mid-state after optional deposit
        uint midMap = c.balances(address(this));
        uint midCbal = address(c).balance;
        uint midThisBal = address(this).balance;

        // Attempt CashOut(amt) and record whether it reverted. This is a top-level try/catch around the state-changing call.
        bool reverted;
        try c.CashOut(amt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        uint afterMap = c.balances(address(this));
        uint afterCbal = address(c).balance;
        uint afterThisBal = address(this).balance;

        // Assert the general rule: if CashOut succeeded then mapping decreased by amt and ether moved accordingly; if it reverted then nothing observable changed by the CashOut call.
        // Note: mid-state captures the state immediately before CashOut so the assertion relates changes to the CashOut outcome.
        assert(
            reverted
            ? (afterMap == midMap && afterCbal == midCbal && afterThisBal == midThisBal)
            : (midMap >= amt && afterMap == midMap - amt && afterCbal + amt == midCbal && afterThisBal == midThisBal + amt)
        );
    }

    // allow receiving ether when testing
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function: deposit an amount, then attempt CashOut and assert invariant
    function run(uint depositAmount, uint withdrawAmount) public payable {
        // ensure this contract has enough balance to forward deposits/withdrawals when needed
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // Read before-values
        uint beforeBalanceMapping = c.balances(address(this));
        uint beforeContractEther = address(c).balance;
        uint beforeThisEther = address(this).balance;

        // Make a Deposit on c if depositAmount >= MinDeposit (Deposit silently ignores small amounts)
        if (depositAmount > 0) {
            // perform deposit with value depositAmount
            c.Deposit{value: depositAmount}();
        }

        // Read after-deposit values
        uint afterDepositBalanceMapping = c.balances(address(this));
        uint afterDepositContractEther = address(c).balance;
        uint afterDepositThisEther = address(this).balance;

        // Now attempt to CashOut withdrawAmount and capture whether it reverted
        bool didRevert;
        try c.CashOut(withdrawAmount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Read final values
        uint finalBalanceMapping = c.balances(address(this));
        uint finalContractEther = address(c).balance;
        uint finalThisEther = address(this).balance;

        /* General rule asserted:
           - If CashOut succeeded (didRevert == false) then mapping balance decreased by withdrawAmount
             and the contract c's Ether balance decreased by withdrawAmount, and this contract's ether
             balance increased by withdrawAmount (modulo gas effects are irrelevant because call uses
             .call and transfer is to this contract so balance arithmetic is exact here).
           - If CashOut reverted then mapping and Ether balances remain equal to their post-deposit values.
        */
        assert(
            (!didRevert &&
                finalBalanceMapping + withdrawAmount == afterDepositBalanceMapping &&
                afterDepositContractEther == finalContractEther + withdrawAmount &&
                finalThisEther == afterDepositThisEther + withdrawAmount)
            ||
            (didRevert &&
                finalBalanceMapping == afterDepositBalanceMapping &&
                finalContractEther == afterDepositContractEther &&
                finalThisEther == afterDepositThisEther)
        );
    }

    // receive to accept Ether from c when CashOut succeeds
    receive() external payable {}
}

