contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try depositing some ether then attempt cashout
    function run(uint depositAmt, uint cashoutAmt) public payable {
        require(true);
        // ensure this contract has enough balance to forward depositAmt
        if (depositAmt > 0) {
            require(address(this).balance >= depositAmt);
            c.Deposit{value: depositAmt}();
        }

        // read balance recorded for this contract in c before cashout
        uint beforeBal = c.balances(address(this));
        uint beforeContractEth = address(c).balance;

        bool reverted;
        // attempt CashOut and catch revert
        try c.CashOut(cashoutAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = c.balances(address(this));
        uint afterContractEth = address(c).balance;

        // General rule:
        // - If call reverted, then recorded balance and contract balance are unchanged.
        // - Otherwise (did not revert): two possibilities
        //    * If cashoutAmt <= beforeBal then recorded balance decreased by cashoutAmt and contract's ETH decreased by cashoutAmt.
        //    * If cashoutAmt > beforeBal then nothing should have changed (function's logic guards), so recorded balance unchanged.
        assert(
            // reverted => no state change
            (reverted && afterBal == beforeBal && afterContractEth == beforeContractEth)
            ||
            // not reverted => either successful cashout when had enough balance
            (!reverted && cashoutAmt <= beforeBal && afterBal + cashoutAmt == beforeBal && beforeContractEth == afterContractEth + cashoutAmt)
            ||
            // or not reverted but call was a no-op because cashoutAmt > beforeBal (function returns without action)
            (!reverted && cashoutAmt > beforeBal && afterBal == beforeBal && afterContractEth == beforeContractEth)
        );
    }

    // allow receiving ETH when c sends funds to this test contract
    receive() external payable {}
}

