contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that drives c and asserts the invariant
    // params: depositAmount to deposit (sent to Deposit), withdrawAmount for CashOut
    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "need funds to deposit");

        // record pre-state observable values
        uint beforeContractBalance = address(c).balance;
        uint beforeMyBalance = c.balances(address(this));

        // make a deposit if depositAmount > 0
        if (depositAmount > 0) {
            // call Deposit sending Ether
            c.Deposit{value: depositAmount}();
        }

        // record post-deposit observed balance
        uint afterDepositMyBalance = c.balances(address(this));
        uint afterDepositContractBalance = address(c).balance;

        // Now attempt CashOut(withdrawAmount) and capture whether it reverted
        bool reverted;
        try c.CashOut(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observations after CashOut
        uint finalContractBalance = address(c).balance;
        uint finalMyBalance = c.balances(address(this));

        // Assert the general rule:
        // 1) balances[address(this)] never increases as a result of CashOut (it either stays same or decreases)
        // 2) If CashOut did not revert then finalContractBalance decreased by exactly the withdrawn amount
        //    and finalMyBalance decreased by exactly the withdrawn amount as well (compared to pre-CashOut state)
        // Note: compare to afterDeposit values so deposit is accounted for.
        assert(
            // (A) balance getter did not increase
            (finalMyBalance <= afterDepositMyBalance)
            // AND (B) if CashOut succeeded then both contract and getter reduced by withdrawAmount
            && (
                reverted
                || (
                    // ensure contract balance decreased by withdrawAmount
                    (afterDepositContractBalance >= withdrawAmount && (afterDepositContractBalance - finalContractBalance) == withdrawAmount)
                    // and the public balances getter decreased by withdrawAmount
                    && (afterDepositMyBalance >= withdrawAmount && (afterDepositMyBalance - finalMyBalance) == withdrawAmount)
                )
            )
        );
    }

    // allow receiving Ether when contract c sends funds back
    receive() external payable {}
}

